function bindLocalPlaybackTarget(o: ObjectRuntime<"chewie_LocalPlaybackTarget">): LocalPlaybackTarget {
  return {
    node: o.node,
    pause: () => o.invoke("pause", {}, 0),
    play: () => o.invoke("play", {}, 0),
    seekTo: (position) => o.invoke("seekTo", { position }, 0),
    setPlaybackSpeed: (speed) => o.invoke("setPlaybackSpeed", { speed }, 0),
    setVolume: (volume) => o.invoke("setVolume", { volume }, 0),
    get: o.get,
    dispose: o.dispose,
  };
}

/** Wraps a `LocalPlaybackTarget` that Dart created and handed over (a method result or a getter). */
export function adoptLocalPlaybackTarget(ref: ObjectRef): LocalPlaybackTarget {
  return bindLocalPlaybackTarget(adoptObject("chewie_LocalPlaybackTarget", ref));
}

